resource "aws_autoscaling_group" "sandbox" {
  for_each = var.sizes

  name                = "${var.name_prefix}-sandbox-${each.key}"
  vpc_zone_identifier = var.subnet_ids
  min_size            = 0
  max_size            = 3 # only claims in flight live here; claimed VMs are detached
  desired_capacity    = 0

  launch_template {
    id      = aws_launch_template.sandbox[each.key].id
    version = "$Latest"
  }

  warm_pool {
    pool_state                  = "Stopped" # a stopped VM costs only its disk
    min_size                    = var.warm_pool_size[each.key] # lite 2, full 2, wide 0 to start
    max_group_prepared_capacity = var.warm_pool_size[each.key]
    instance_reuse_policy {
      reuse_on_scale_in = false # a used VM never goes back to the pool
    }
  }

  # The VM finishes setup (FCP Lab started once, images pulled, disk warmed) before it is stopped.
  initial_lifecycle_hook {
    name                 = "finish-setup"
    lifecycle_transition = "autoscaling:EC2_INSTANCE_LAUNCHING"
    heartbeat_timeout    = 1800
    default_result       = "ABANDON"
  }

  # + dynamic "tag" blocks (propagate_at_launch) for var.tags, ai-agents:managed=true, ai-agents:size
}

resource "aws_autoscaling_group" "spot" {
  for_each = { for k, v in var.sizes : k => v if k != "wide" }
  name                = "${var.name_prefix}-sandbox-${each.key}-spot"
  vpc_zone_identifier = var.subnet_ids
  min_size            = 0
  max_size            = 3
  desired_capacity    = 0
  mixed_instances_policy {
    instances_distribution {
      on_demand_percentage_above_base_capacity = 0
      spot_allocation_strategy                 = "price-capacity-optimized"
    }
    launch_template {
      launch_template_specification {
        launch_template_id = aws_launch_template.sandbox[each.key].id
        version            = "$Latest"
      }
      dynamic "override" {
        for_each = [for family in ["m8i", "m7i", "m6i"] : replace(each.value, "m8i", family)]
        content { instance_type = override.value }
      }
    }
  }
}

"""Sandbox sweeper: every 15 minutes, remove VMs and disks that no live run owns. Based on aws-vm-autostop."""
import datetime as dt
import json
import os

import boto3

ec2, autoscaling = boto3.client("ec2"), boto3.client("autoscaling")
DRY_RUN = os.environ.get("DRY_RUN", "true") == "true"  # start dry, like dev-vm-autostop


def handler(event, context):
    now = dt.datetime.now(dt.UTC)
    for inst in managed_instances(states=["running", "stopped"]):  # tag ai-agents:managed=true only
        tags = {t["Key"]: t["Value"] for t in inst.get("Tags", [])}
        if "ai-agents:run-id" in tags and parse(tags.get("ai-agents:lease-until")) < now:
            act("terminate", inst["InstanceId"], "lease expired: no live run owns this VM")
        elif inst["State"]["Name"] == "stopped" and stopped_since(inst) < now - dt.timedelta(hours=72):
            act("terminate", inst["InstanceId"], "stopped for over 72 h; its work is already saved")
        elif "aws:autoscaling:groupName" in tags and inst["LaunchTime"] < now - dt.timedelta(hours=24):
            act("recycle", inst["InstanceId"], "warm VM older than 24 h; the pool refills from the newest image")
    for vol in managed_volumes(status="available"):
        act("delete-volume", vol["VolumeId"], "orphaned disk")

def act(action: str, resource_id: str, reason: str) -> None:
    print(json.dumps({"action": action, "id": resource_id, "reason": reason, "dry_run": DRY_RUN}))
    if DRY_RUN:
        return
    if action == "terminate":
        ec2.terminate_instances(InstanceIds=[resource_id])
    elif action == "recycle":
        autoscaling.terminate_instance_in_auto_scaling_group(InstanceId=resource_id, ShouldDecrementDesiredCapacity=False)
    else:
        ec2.delete_volume(VolumeId=resource_id)

